action.mutation:
mutation ($productPayload: [ProductCreatePayloadInput!]!, $strategyPayload: [ProductStrategyCreatePayloadInput!]!, $processPayload: [ProductStrategyProcessCreatePayloadInput!]!) {
  createProduct(payload: $productPayload) {
    id
  }
  createProductStrategy(payload: $strategyPayload) {
    id
  }
  createProductStrategyProcess(payload: $processPayload) {
    id
  }
}
